                                                                                                                                                                                                     
  CREATE TABLE "AUTH_USER"                                                                                                                                                                
   (	"USER_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                          
	"CREATION_DATE" DATE NOT NULL ENABLE,                                                                                                                                                               
	"UPDATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                          
	"UPDATE_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                 
	"REMARK" NVARCHAR2(512),                                                                                                                                                                            
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                        
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                 
	"USERNAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                           
	"PASSWORD" NVARCHAR2(128) NOT NULL ENABLE,                                                                                                                                                          
	"JOB_NUMBER" VARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                          
	"MOBILE" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                             
	"IS_ENABLED" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                      
	"LAST_LOGIN_TIME" NVARCHAR2(32),                                                                                                                                                                    
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                       
	 PRIMARY KEY ("USER_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                
   ) ;                                                                                                                                                                                               

